/// <summary>
/// Scoped service that tracks low-stock alert counts per warehouse.
/// Fires <see cref="OnAlertCountChanged"/> whenever new data arrives so
/// all subscribed components can update, even if they didn't trigger the poll.
/// </summary>
public sealed class InventoryAlertService : IDisposable
{
    private readonly Random _random = new();
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;

    public int CurrentAlertCount { get; private set; }

    public event Action? OnAlertCountChanged;

    /// <summary>Simulates a database query returning low-stock item count.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate latency-free DB call; return random 0–15.
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Begin polling every 10 seconds for the given warehouse.
    /// Multiple callers share one timer; polling stops when the last one unsubscribes.
    /// </summary>
    public void StartPolling(string warehouseId, Func<string> currentWarehouseAccessor)
    {
        _subscriberCount++;
        if (_timer is not null) return; // already running

        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        var token = _cts.Token;

        _ = Task.Run(async () =>
        {
            // Immediately fetch once before waiting for the first tick.
            await PollOnceAsync(currentWarehouseAccessor());

            while (!token.IsCancellationRequested)
            {
                try
                {
                    if (!await _timer.WaitForNextTickAsync(token)) break;
                    await PollOnceAsync(currentWarehouseAccessor());
                }
                catch (OperationCanceledException)
                {
                    break;
                }
            }
        }, token);
    }

    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount > 0) return;

        _cts?.Cancel();
        _timer?.Dispose();
        _timer = null;
        _cts?.Dispose();
        _cts = null;
    }

    private async Task PollOnceAsync(string warehouseId)
    {
        CurrentAlertCount = await GetLowStockCountAsync(warehouseId);
        OnAlertCountChanged?.Invoke();
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _timer?.Dispose();
        _cts?.Dispose();
    }
}

