@inject sv_4b506b2b70134f9490a28f67d210c349.Services.WarehouseState WarehouseState
@implements IDisposable

<select class="form-select form-select-sm"
        value="@WarehouseState.SelectedWarehouseId"
        @onchange="OnWarehouseChanged"
        style="max-width: 320px;">
    @foreach (var wh in sv_4b506b2b70134f9490a28f67d210c349.Services.WarehouseState.Warehouses)
    {
        <option value="@wh.Id">@wh.Name</option>
    }
</select>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += OnStateChanged;
    }

    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        WarehouseState.SetWarehouse(e.Value?.ToString() ?? "WH-001");
    }

    private void OnStateChanged() => InvokeAsync(StateHasChanged);

    public void Dispose() => WarehouseState.OnChange -= OnStateChanged;
}

@inject sv_4b506b2b70134f9490a28f67d210c349.Services.InventoryAlertService AlertService
@implements IDisposable

@if (AlertService.CurrentAlertCount > 0)
{
    <span class="badge bg-danger rounded-pill ms-2">@AlertService.CurrentAlertCount</span>
}
else
{
    <span class="badge bg-success rounded-pill ms-2">0</span>
}

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertCountChanged += _handler;
    }

    public void Dispose()
    {
        if (_handler is not null)
            AlertService.OnAlertCountChanged -= _handler;
    }
}

