@page "/dashboard"
@rendermode InteractiveServer
@inject sv_4b506b2b70134f9490a28f67d210c349.Services.WarehouseState WarehouseState
@inject sv_4b506b2b70134f9490a28f67d210c349.Services.InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Current Warehouse</h5>
                <p class="card-text fs-4">
                    @GetWarehouseName(WarehouseState.SelectedWarehouseId)
                </p>
                <p class="text-muted">ID: @WarehouseState.SelectedWarehouseId</p>
            </div>
        </div>
    </div>
    <div class="col-md-6">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Low-Stock Alerts</h5>
                <p class="card-text fs-1">
                    @if (AlertService.CurrentAlertCount > 0)
                    {
                        <span class="text-danger">⚠ @AlertService.CurrentAlertCount items</span>
                    }
                    else
                    {
                        <span class="text-success">✓ All stocked</span>
                    }
                </p>
                <p class="text-muted">Refreshes every 10 seconds</p>
            </div>
        </div>
    </div>
</div>

@code {
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    protected override void OnInitialized()
    {
        _warehouseHandler = () => InvokeAsync(StateHasChanged);
        WarehouseState.OnChange += _warehouseHandler;

        _alertHandler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertCountChanged += _alertHandler;

        // Start polling; pass an accessor so the timer always reads the current warehouse.
        AlertService.StartPolling(
            WarehouseState.SelectedWarehouseId,
            () => WarehouseState.SelectedWarehouseId);
    }

    private static string GetWarehouseName(string id) =>
        WarehouseState.Warehouses.FirstOrDefault(w => w.Id == id).Name ?? id;

    public void Dispose()
    {
        if (_warehouseHandler is not null)
            WarehouseState.OnChange -= _warehouseHandler;

        if (_alertHandler is not null)
            AlertService.OnAlertCountChanged -= _alertHandler;

        AlertService.StopPolling();
    }
}

